    'hotels-training' => 
    array (
      'title' => 'برامج تدريب موظفي الفنادق حسب القسم',
      'subtitle' => 'ما الذي يتدرب عليه كل قسم فندقي، وبأي ترتيب يُقدَّم التدريب، وكيف تُثبت القدرة قبل أن يعمل الموظف دون إشراف.',
      'body' => '<h2>ما التدريب الذي يحتاجه كل قسم في الفندق؟</h2><p>لكل قسم مساره الخاص ضمن المنهج الرئيسي الذي طورته ألتوس للاستشارات في الرياض انطلاقاً من معايير تشغيلية مجرّبة ميدانياً. ويتدرج المحتوى من المجال المهني إلى المسار ثم الوحدة ثم الدرس، يليها التقييم والاعتماد، فيكون لكل دور طريق واضح.</p><ul><li><strong>مكتب الاستقبال:</strong> إجراءات الوصول والمغادرة، وتسجيل الضيف وخصوصيته، وتوزيع الغرف، ومعالجة الشكاوى، والبيع الإضافي، والتدقيق الليلي.</li><li><strong>التدبير الفندقي:</strong> تسلسل تنظيف الغرفة، ومعايير السرير ودورة المياه، وسلامة المواد الكيميائية، والمفقودات، والمغسلة، والمناطق العامة، والتفتيش.</li><li><strong>الأغذية والمشروبات:</strong> تسلسل الخدمة، والاستقبال والإجلاس، وخدمة الطاولة والمشروبات، والولائم، وإجراءات نقاط البيع.</li><li><strong>المطبخ:</strong> سلامة الغذاء، وضبط درجات الحرارة، والتخزين والاستلام، والتعامل مع مسببات الحساسية، وسلامة السكاكين، وضبط الهدر.</li><li><strong>المبيعات والإيرادات والحجوزات:</strong> المبيعات والتسويق، وإجراءات الحجز، والتوزيع، وأساسيات إدارة الإيرادات.</li><li><strong>تجربة الضيف والجودة والتدقيق:</strong> معالجة إخفاقات الخدمة، والالتزام بمعايير العلامة والإجراءات، وتفتيش الجودة.</li><li><strong>الأمن والسلامة:</strong> السلامة من الحريق، والاستجابة للطوارئ، وإجراءات الأمن لكل موظف.</li></ul><h2>بأي ترتيب يُقدَّم تدريب موظفي الفنادق؟</h2><p>تأتي السلامة والأساسيات أولاً، ثم مهارات الدور، ثم تقييم المعيار نفسه.</p><ol><li>أساسيات الفندقة والتعريف بالمنشأة والسلامة لكل موظف</li><li>المتطلبات المسبقة للدور، مثل سلامة المواد الكيميائية في التدبير الفندقي أو سلامة الغذاء ومسببات الحساسية في المطبخ</li><li>وحدات الدور بدروس تطبيقية قصيرة بالفيديو أو ملفات PDF أو العروض أو الصوت</li><li>تقييم نظري، ثم تقييم عملي يجريه المشرف</li><li>شهادة، أو خطة عمل وإعادة تقييم عند ظهور فجوة</li></ol><h2>هل يمكن أن يتبع التدريب معايير فندقنا الخاصة؟</h2><p>نعم. المنصة قابلة للتخصيص بهوية كل منشأة، وتُضاف إجراءاتك وسياساتك وقوائم التحقق المعتمدة لديك إلى جانب المنهج، مع تسجيل إقرار الموظفين بكل إصدار. ويجيب مساعد الذكاء الاصطناعي عن أسئلة الموظفين من هذا المحتوى المعتمد وحده.</p><h2>هل يتوفر التدريب للموظفين الذين لا يقرؤون العربية أو الإنجليزية؟</h2><p>الدروس ثنائية اللغة بالعربية والإنجليزية، وتدعم مساحة عمل الموظفين كذلك الهندية والأردية والفلبينية والبنغالية والنيبالية والمالايالامية، لتلائم الفرق متعددة الجنسيات العاملة في فنادق السعودية.</p><p>استكشف <a href="/ar/courses">كتالوج الدورات الكامل</a>، أو اتبع <a href="/ar/learning-paths">مساراً تعليمياً حسب الدور</a>، أو اقرأ <a href="/ar/hotels">كيف تعتمد الفنادق المنصة</a>.</p>',
      'cta_label' => 'اطّلع على الكتالوج الكامل',
      'meta_title' => 'برامج تدريب موظفي الفنادق حسب القسم في السعودية',
      'meta_description' => 'برامج تدريب موظفي الفنادق حسب القسم، من الاستقبال إلى المطبخ، مع تقييم عملي وشهادات قابلة للتحقق للفرق العاملة في السعودية.',
      'focus_keyword' => 'برامج تدريب موظفي الفنادق',
    ),
    'certificates-info' => 
    array (
      'title' => 'شهادات التدريب الفندقي والتحقق منها',
      'subtitle' => 'ما الذي توثقه شهادة أكاديمية الضيافة، ومتى تُصدر، وكيف يتحقق صاحب العمل خلال ثوانٍ من صحتها وسريانها.',
      'body' => '<h2>متى تُصدر شهادة أكاديمية الضيافة؟</h2><p>تُصدر الشهادة عندما يكمل المتدرب كل درس إلزامي في الدورة ويجتاز تقييمها بدرجة النجاح المحددة لتلك الدورة أو أعلى منها. وتُصدر شهادة البرنامج عند إكمال جميع دوراته. والغاية من الاعتماد أن يعكس قدرة مُقيَّمة، لا مجرد حضور.</p><h2>ما الذي توثقه شهادة التدريب الفندقي؟</h2><p>توثق كل شهادة ما يحتاجه صاحب العمل من معلومات فقط.</p><ul><li>اسم المتدرب</li><li>الدورة أو البرنامج المكتمل</li><li>تاريخ الإكمال والدرجة النهائية</li><li>رقم شهادة فريد ورمز تحقق ورمز استجابة سريعة (QR)</li><li>تاريخ انتهاء حين يتطلب الموضوع تجديداً دورياً، مثل السلامة وسلامة الغذاء</li></ul><h2>كيف أتحقق من شهادة تدريب فندقي؟</h2><p>استخدم صفحة التحقق العامة، ولا حاجة إلى حساب.</p><ol><li>افتح <a href="/ar/verify">صفحة التحقق من الشهادات</a>.</li><li>أدخل رمز التحقق المطبوع على الشهادة، أو امسح رمز QR الخاص بها.</li><li>اقرأ الحالة الظاهرة: سارية أو منتهية أو ملغاة أو غير موجودة.</li></ol><p>تعرض النتيجة السارية اسم المتدرب والموضوع وتاريخ الإصدار، ولا شيء آخر عن الشخص.</p><h2>لماذا قد تظهر الشهادة ملغاة؟</h2><p>تُلغى الشهادة إذا صدرت بالخطأ، أو إذا تبيّن أن نتيجة التقييم التي بُنيت عليها غير صحيحة، أو بطلب من الجهة المُصدِرة. وتبقى الشهادة الملغاة قابلة للتحقق وتظهر بحالة «ملغاة» بدلاً من أن تختفي، حتى لا تُقدَّم نسخة سابقة على أنها سارية.</p><h2>من يُصدر الشهادات؟</h2><p>تُصدر الشهادات عبر منصة ألتوس للمعرفة والأداء الفندقي التي تشغّلها ألتوس للاستشارات في الرياض بالمملكة العربية السعودية. وتوثق الشهادة إكمال شخص محدد لدورة أو برنامج محدد في تاريخ محدد، وهي ليست رخصة ولا موافقة تنظيمية ولا إفادة بأن حاملها مؤهل لدور بعينه.</p><p>تصفّح <a href="/ar/programs">برامج الشهادات</a> المتاحة، أو <a href="/ar/contact">اسأل فريق الأكاديمية</a> عن اعتماد موظفي فندقك.</p>',
      'cta_label' => 'تحقق من شهادة',
      'meta_title' => 'التحقق من شهادة تدريب فندقي | أكاديمية الضيافة',
      'meta_description' => 'التحقق من شهادة تدريب فندقي صادرة عن أكاديمية الضيافة برمز التحقق أو رمز QR، وما الذي توثقه الشهادة ومتى تنتهي ولماذا قد تُلغى.',
      'focus_keyword' => 'التحقق من شهادة تدريب فندقي',
    ),
    'contact' => 
    array (
      'title' => 'تواصل مع أكاديمية الضيافة',
      'subtitle' => 'أخبرنا عن منشآتك وفريقك، وسنعود إليك بهيكل عمل لا بكتيّب تعريفي.',
      'body' => '<h2>كيف أطلب تدريباً فندقياً لمنشأتي؟</h2><p>أرسل طلبك بشأن تدريب الفنادق في الرياض أو في أي منطقة أخرى من المملكة عبر النموذج في هذه الصفحة، وسيتواصل معك أحد أعضاء فريق أكاديمية الضيافة في ألتوس للاستشارات بالرياض، المملكة العربية السعودية، لترتيب مكالمة. لا توجد رسائل بريد آلية متسلسلة، ولا تُمرَّر بياناتك إلى أي طرف ثالث.</p><h2>ما المعلومات التي أذكرها في طلبي؟</h2><p>تتيح لنا بعض المعلومات الأساسية أن نرد بهيكل عمل واضح بدلاً من عرض تقديمي عام.</p><ul><li>الفنادق والمدن المعنية</li><li>الأقسام التي تريد البدء بها</li><li>العدد التقريبي للموظفين في كل قسم</li><li>اللغات التي يحتاجها موظفوك: العربية أو الإنجليزية أو لغات العمالة مثل الهندية والأردية والفلبينية والبنغالية والنيبالية والمالايالامية</li><li>أي موعد نهائي، مثل افتتاح منشأة أو جولة تفتيش</li></ul><h2>ماذا يحدث بعد التواصل؟</h2><p>الإجراء قصير ويتولاه أشخاص لا أنظمة آلية.</p><ol><li>نرد عليك لترتيب مكالمة تعريفية.</li><li>نناقش منشآتك ومسمياتها الوظيفية ومعاييرها الحالية.</li><li>نقترح هيكلاً للأقسام والأدوار والتدريب الإلزامي لفريقك.</li></ol><h2>هل يمكنني التواصل مع ألتوس للاستشارات في موضوع غير التدريب؟</h2><p>نعم. تقدم ألتوس للاستشارات أيضاً خدماتها لملاك الفنادق والمستثمرين في السعودية ودول الخليج في تطوير الفنادق وتمثيل الملاك، ودعم ما قبل الافتتاح، والتشغيل، وتجربة الضيف، والأداء التجاري، ونمو الأعمال بوجه عام. تعرّف على <a href="/ar/altus">ألتوس للاستشارات وخدماتها</a>.</p><h2>إلى أين أتوجه باستفسار عن شهادة؟</h2><p>للتأكد من صحة شهادة، استخدم <a href="/ar/verify">صفحة التحقق من الشهادات</a> مباشرة دون الحاجة إلى تقديم طلب. ولطلب نسخة من سجلك التدريبي أو تصحيحه، تواصل مع مسؤول النظام لدى جهة عملك أو راسلنا عبر هذه الصفحة.</p><p>قبل أن تراسلنا، قد يفيدك الاطلاع على <a href="/ar/hotels">كيف تعمل المنصة للفنادق</a> أو تصفّح <a href="/ar/courses">كتالوج الدورات</a>.</p>',
